class Command(BaseCommand):
    help = "Seed district_office table from SQL data (requires circleoffice to be seeded first)"

    def handle(self, *args, **options):
        circle_map = {co.id: co for co in CircleOffice.objects.all()}
        if not circle_map:
            self.stdout.write(self.style.ERROR(
                "No CircleOffice records found. Run seed_circleoffice_designation first."
            ))
            return

        created = updated = 0
        for pk, co_id, name, address, nomanp, orderno in DISTRICT_OFFICES:
            co = circle_map.get(co_id)
            if co is None:
                self.stdout.write(self.style.WARNING(
                    f"  Skipping id={pk}: CircleOffice id={co_id} not found"
                ))
                continue
            _, made = DistrictOffice.objects.update_or_create(
                id=pk,
                defaults={
                    "circleoffice": co,
                    "districtofficename": name,
                    "officeaddress": address,
                    "nomanp": nomanp,
                    "orderno": orderno,
                },
            )
            if made:
                created += 1
            else:
                updated += 1

        self.stdout.write(self.style.SUCCESS(
            f"DistrictOffice: {created} created, {updated} updated"
        ))
